BEGIN READ ONLY;
SELECT json_build_object('identity',json_build_object('database',current_database(),'session',session_user,'pid',pg_backend_pid(),'clock',clock_timestamp(),'stockholm',clock_timestamp() AT TIME ZONE 'Europe/Stockholm'),'migrations',(SELECT json_agg(version ORDER BY version) FROM supabase_migrations.schema_migrations));
SELECT json_build_object('function',p.proname,'definition',pg_get_functiondef(p.oid),'acl',p.proacl,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('close_year_atomic','close_year_unchecked_inventory','assert_vat_year_coverage','lock_accounting_year_boundary','lock_inventory_boundary','book_transaction_atomic','ensure_vat_periods','close_vat_period_atomic','customer_invoice_year_end_fiscal_year');
SELECT json_build_object('table',c.relname,'rls',c.relrowsecurity,'acl',c.relacl,'columns',(SELECT json_agg(json_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'default',pg_get_expr(d.adbin,d.adrelid))) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT json_agg(pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid=c.oid),'indexes',(SELECT json_agg(indexdef) FROM pg_indexes WHERE schemaname='public' AND tablename=c.relname),'policies',(SELECT json_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname='public' AND tablename=c.relname),'triggers',(SELECT json_agg(json_build_object('trigger',pg_get_triggerdef(t.oid),'function',pg_get_functiondef(t.tgfoid))) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('closed_years','profiles','vat_periods');
COMMIT;
